$path = "reset-password.html"
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $path), $bytes)
$check = [System.IO.File]::ReadAllText((Join-Path (Get-Location) $path))
if ($check.Contains("At least 8 characters")) { Write-Output "New password validation UI: OK" } else { Write-Output "New password validation UI: MISSING" }
if ($check.Contains("logo.png")) { Write-Output "Logo reference: OK" } else { Write-Output "Logo reference: MISSING" }
Write-Output "Now run: firebase deploy --only hosting"
